using Godot;
using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
namespace Arconist.GodotApp;
public static class LinkedValidation
{
 private sealed class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
 public static void Run(Node owner,SpatialTrack track,string evidenceDir)
 {
  int passed=0,failed=0;var outcomes=new List<object>();
  void Check(bool ok,string why){if(!ok)throw new Exception(why);}
  void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});GD.Print("PASS R009 "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});GD.Print("FAIL R009 "+name+": "+e.Message);}}
  string Load(string n)=>Godot.FileAccess.GetFileAsString("res://content/"+n);
  Kernel New(string name="native_linked_arc_successors.aff"){var k=new Kernel(Chart.Parse(Load(name)));k.Frame(0);k.Frame(3002);return k;}
  void F(Kernel k,int e)=>k.Frame(e+3002);
  SkyContact Pick(ArcState a){var screen=track.Camera.UnprojectPosition(SpatialTrack.World(a.TargetX,a.TargetY,0));Check(track.PickSky(screen,out var sky),"actual camera pick");return sky;}
  Test("all fourteen preserved and new chart resources accessible",()=>{foreach(string n in new[]{"practice.aff","ordinary_two_tap.aff","mixed_practice.aff","native_hold.aff","hold_first.aff","tap_first.aff","audible_practice.aff","audible_aff120.aff","sky_practice.aff","native_moving_arc.aff","arctap_practice.aff","native_arc_tap.aff","linked_practice.aff","native_linked_arc_successors.aff"})Check(Chart.Parse(Load(n)).JudgmentUnits>0,n);});
  Test("two real arc roots and distinct junction geometry",()=>{var k=New();F(k,1000);track.Refresh(k);Check(track.ArcVisualCount==2&&track.ArcVisual(k.Arcs[0].Id)!=track.ArcVisual(k.Arcs[1].Id)&&track.JunctionVisual(k.Arcs[0].Id)!.Mesh is BoxMesh&&track.JunctionVisual(k.Arcs[1].Id)==null,"pair and connector nodes");});
  Test("junction endpoints use native samples and coherent parent translations",()=>{var k=New();F(k,2000);track.Refresh(k);var a=k.Arcs[0];var b=k.Arcs[1];var endpoint=SpatialTrack.World(a.Geometry.X1,a.Geometry.Y1,SpatialTrack.HoldDepth(k,a.Start)+a.Geometry.Z);var start=SpatialTrack.World(b.Geometry.X0,b.Geometry.Y0,SpatialTrack.HoldDepth(k,b.Start));Check(endpoint.DistanceTo(start)<2*SpatialTrack.Unit&&track.JunctionVisual(a.Id)!.Position.IsEqualApprox(endpoint),"native quantization seam within2 internal units");});
  Test("one current target stays green across exclusive junction",()=>{var k=New();F(k,1000);k.DownSpatial(4002,42,0,Pick(k.Arcs[0]));foreach(int e in new[]{1001,2000,2001,2002}){F(k,e);track.Refresh(k);var visible=k.Arcs.Select(a=>track.ArcTarget(a.Id)!).Where(m=>m.Visible).ToArray();Check(visible.Length==1&&((StandardMaterial3D)visible[0].MaterialOverride).AlbedoColor==new Color("a5f56d"),"continuous single green targetE"+e);}Check(!track.ArcTarget(k.Arcs[0].Id)!.Visible&&track.ArcTarget(k.Arcs[1].Id)!.Visible,"target moved to successor");});
  Test("weighted checkpoint marker is distinct and resolves one visual",()=>{var k=New();F(k,1000);track.Refresh(k);var a=k.Arcs[0];var root=track.ArcVisual(a.Id)!;var marker=root.GetNode<MeshInstance3D>("Checkpoint1500");Check(((BoxMesh)marker.Mesh).Size.X==150*SpatialTrack.Unit&&!root.HasNode("Checkpoint1750"),"folded marker/removed record");k.DownSpatial(4002,42,0,Pick(a));F(k,1125);F(k,1375);track.Refresh(k);Check(k.RecorderTrace.Count==2&&a.Records[1].Resolved&&((StandardMaterial3D)marker.MaterialOverride).AlbedoColor==new Color("a5f56d"),"one visual/two genuine recorder calls");});
  Test("both camera views sustain one contact without new DOWN",()=>{foreach(bool alternate in new[]{false,true}){track.SetView(alternate);var k=New();F(k,1000);k.DownSpatial(4002,42,0,Pick(k.Arcs[0]));foreach(int e in new[]{1001,1125,1375,2000,2001,2002,2126,2376,2626}){F(k,e);track.Refresh(k);}Check(k.Pure==7&&k.Contacts.Single().Id==0&&k.Arcs[1].Holding,"camera continuity");}track.SetView(false);});
  Test("actual resized viewport keeps linked target projection aligned",()=>{var viewport=(SubViewport)track.GetViewport();var container=(SubViewportContainer)viewport.GetParent();var old=viewport.Size;bool stretch=container.Stretch;container.Stretch=false;try{foreach(var size in new[]{new Vector2I(610,550),new Vector2I(732,660)}){viewport.Size=size;Check(viewport.Size==size,"actual resize");var k=New();F(k,1000);k.DownSpatial(4002,42,0,Pick(k.Arcs[0]));F(k,2001);track.Refresh(k);Check(ArcSpatial.Matches(k.Arcs[1].TargetX,k.Arcs[1].TargetY,Pick(k.Arcs[1]))&&k.Arcs[1].Holding,"resized successor projection");}}finally{viewport.Size=old;container.Stretch=stretch;}});
  Test("renderer cannot mutate links ownership group counters or records",()=>{var k=New();F(k,1000);k.DownSpatial(4002,42,0,Pick(k.Arcs[0]));F(k,1375);string State()=>JsonSerializer.Serialize(new{k.Score,k.Health,k.RecorderCalls,arcs=k.Arcs.Select(a=>new{a.Id,a.Holding,a.ResolutionWrites,a.Records,owner=a.Color.Owner,predecessor=a.Predecessor?.Id,successors=a.Successors.Select(b=>b.Id)}),groups=k.ArcGroups.Select(g=>new{g.Active,g.Accepted,g.CacheRelated,g.Window,g.TimestampHistory})});string before=State();for(int i=0;i<30;i++)track.Refresh(k);Check(before==State(),"read-only renderer");});
  Test("paused junction mesh/cache freezes for60seconds",()=>{var k=New();F(k,1000);k.DownSpatial(4002,42,0,Pick(k.Arcs[0]));F(k,2000);track.Refresh(k);var position=track.JunctionVisual(k.Arcs[0].Id)!.Position;int pure=k.Pure;k.Pause(5002);k.Frame(65002);track.Refresh(k);Check(track.JunctionVisual(k.Arcs[0].Id)!.Position==position&&k.Pure==pure&&k.Arcs[0].Color.Owner==0,"frozen");k.Resume(65002);k.Frame(65003);track.Refresh(k);Check(k.Arcs[1].Holding&&k.Pure==4,"resume contact at junction");});
  Test("UP then frame clears activity while group cache stays set",()=>{var k=New();F(k,1000);k.DownSpatial(4002,42,0,Pick(k.Arcs[0]));foreach(int e in new[]{1125,1375,2001,2126,2376,2626,2876})F(k,e);k.Up(42);Check(k.Arcs[1].Holding,"prior-frame activity");F(k,2877);track.Refresh(k);Check(!k.ArcGroups[0].Active&&k.ArcGroups[0].CacheRelated&&((StandardMaterial3D)track.ArcTarget(k.Arcs[1].Id)!.MaterialOverride).AlbedoColor==new Color("f4f7ff"),"correct cleanup feedback");});
  Test("complete extended chart through production bridge and 3D nodes",()=>{var clock=new Clock();var session=new GameplaySession(clock);session.Start(Load("linked_practice.aff"));clock.Milliseconds=3002;session.Frame();for(int e=1;e<=12502;e++){clock.Milliseconds=e+3002;session.Frame();if(e==4000){track.Refresh(session.Core);session.Pointer(100,0,Pick(session.Core!.Arcs[0]),true);}if(e%100==0)track.Refresh(session.Core);}track.Refresh(session.Core);Check(session.Core!.Result!.Score==10000031&&session.HeldCount==0&&session.Core.Arcs.All(a=>!track.ArcVisual(a.Id)!.Visible),"results/cleanup");});
  Test("restart and menu discard all old junction group and meshes",()=>{var k=New();track.Refresh(k);var old=track.ArcVisual(k.Arcs[0].Id)!;var group=k.ArcGroups[0];var fresh=New();track.Refresh(fresh);Check(!old.IsInsideTree()&&!ReferenceEquals(group,fresh.ArcGroups[0])&&fresh.Arcs[0].Color.Owner==-1,"fresh state");track.Refresh(null);Check(track.ArcVisualCount==0,"menu");});
  track.Refresh(null);track.SetView(false);File.WriteAllText(Path.Combine(evidenceDir,"linked-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,humanQualification="PENDING"},new JsonSerializerOptions{WriteIndented=true}));GD.Print($"R009 headless: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");owner.GetTree().Quit(failed==0?0:1);
 }
}
